SELECT COUNT(1)
FROM favorite
WHERE user_id = #{userId}

    AND target_type = #{targetType}

SELECT id, user_id AS userId, target_type AS targetType, target_id AS targetId, created_at AS createdAt FROM favorite WHERE user_id = #{userId}
AND target_type = #{targetType}
ORDER BY id DESC LIMIT #{offset}, #{size}

SELECT d.id, d.name AS title, d.price, d.average_score AS score, di.image_url AS imageUrl FROM dish d LEFT JOIN dish_image di ON di.dish_id = d.id WHERE d.id IN
#{dishId}
ORDER BY d.id ASC, di.is_cover DESC, di.sort_order ASC, di.id ASC

SELECT sp.id, sp.title, sp.dish_name AS dishName, sp.price, sp.score, spi.image_url AS imageUrl FROM student_post sp LEFT JOIN student_post_image spi ON spi.post_id = sp.id WHERE sp.id IN
#{postId}
ORDER BY sp.id ASC, spi.sort_order ASC, spi.id ASC

