UPDATE dish
SET favorite_count = favorite_count + 1
WHERE id = #{id}

UPDATE dish
SET favorite_count = CASE WHEN favorite_count > 0 THEN favorite_count - 1 ELSE 0 END
WHERE id = #{id}

UPDATE student_post
SET favorite_count = favorite_count + 1
WHERE id = #{id}

UPDATE student_post
SET favorite_count = CASE WHEN favorite_count > 0 THEN favorite_count - 1 ELSE 0 END
